<script setup>
import {computed,ref,nextTick} from 'vue'
import {safeUrl} from '../shared'
const props=defineProps({chronology:Object,tree:Object,selected:String,selectedEvent:String,compact:Boolean})
const emit=defineEmits(['select'])
const shell=ref(null),scroller=ref(null),focus=ref(''),zoom=ref(1)
const colors=['#a91638','#397ba2','#448d7a','#9574a9','#bc893b','#557b97','#b26880']
const categories=computed(()=>props.tree.nodes.filter(n=>n.node_type==='category'))
const events=computed(()=>props.chronology?.events||[])
const years=[2016,2017,2018,2019,2020,2021,2022,2023,2024,2025,2026]
const bucket=e=>Math.max(2016,Math.min(2026,Number(e.year)))
const layout=computed(()=>{let y=50;const pts=[],lanes=[];for(const [i,c] of categories.value.entries()){const es=events.value.filter(e=>e.category_id===c.id).sort((a,b)=>a.year-b.year||a.topic_id.localeCompare(b.topic_id));const counts={};for(const e of es)counts[bucket(e)]=(counts[bucket(e)]||0)+1;const height=Math.max(100,Math.max(1,...Object.values(counts))*48+32);const used={};for(const e of es){let b=bucket(e),row=used[b]||0;used[b]=row+1;pts.push({...e,x:220+years.indexOf(b)*148,y:y+30+row*48,tone:colors[i]})}lanes.push({...c,y,height,tone:colors[i],count:es.length});y+=height}return {points:pts,lanes,height:y+15}})
const width=1830
const active=computed(()=>layout.value.points.find(p=>p.id===focus.value)||layout.value.points.find(p=>p.id===props.selectedEvent)||layout.value.points.find(p=>p.topic_id===props.selected))
const edges=computed(()=>{const by=new Map(layout.value.points.map(p=>[p.id,p]));return (props.chronology?.edges||[]).map(e=>({...e,from:by.get(e.source),to:by.get(e.target)})).filter(e=>e.from&&e.to)})
const neighbors=computed(()=>new Set([active.value?.id,...edges.value.filter(e=>e.source===active.value?.id||e.target===active.value?.id).flatMap(e=>[e.source,e.target])]))
const path=e=>{const x=e.from.x+6,tx=e.to.x-6;return `M${x},${e.from.y} C${x+Math.max(45,Math.abs(tx-x)/2)},${e.from.y} ${tx-Math.max(45,Math.abs(tx-x)/2)},${e.to.y} ${tx},${e.to.y}`}
function select(p){focus.value=p.id;emit('select',p)}
async function fullScreen(){if(document.fullscreenElement)await document.exitFullscreen?.();else await shell.value?.requestFullscreen?.()}
function reset(){focus.value='';zoom.value=1;scroller.value?.scrollTo({top:0,left:0,behavior:'smooth'})}
const short=(value,max=108)=>{const s=String(value||'');let n=0,out='';for(const c of s){n+=c.charCodeAt(0)>255?12.4:6.7;if(n>max)return out+'…';out+=c}return out}
function fit(){zoom.value=Math.min(1,(scroller.value?.clientWidth||width)/width)}
</script>
<template><div ref="shell" class="chronology" :class="{compact}"><div class="chronology-toolbar"><div><b>{{chronology?.topic_count||0}}</b> 个技术点 <span>·</span> <b>{{events.length}}</b> 个时间节点 <span>·</span> <b>{{categories.length}}</b> 个技术层</div><div class="chronology-controls"><button @click="zoom=Math.max(.25,zoom-.1)" aria-label="缩小技术时间图">−</button><span>{{Math.round(zoom*100)}}%</span><button @click="zoom=Math.min(1.5,zoom+.1)" aria-label="放大技术时间图">＋</button><button @click="fit">全图</button><button @click="reset">复位</button><button @click="fullScreen">全屏</button></div></div><div ref="scroller" class="chronology-scroller"><div :style="{width:width*zoom+'px'}"><div class="chronology-years" :style="{width:width*zoom+'px',height:38*zoom+'px'}"><svg :viewBox="`0 0 ${width} 38`"><rect width="1830" height="38" fill="#fcfafb"/><text x="15" y="24" font-size="14" fill="#6c788b">代表成果时间</text><text v-for="(year,i) in years" :key="year" :x="220+i*148" y="24" text-anchor="middle" font-size="14" fill="#6c788b">{{year===2016?'2016 及以前':year}}</text></svg></div><svg class="chronology-svg" :viewBox="`0 0 ${width} ${layout.height}`" role="img" aria-label="人工智能70关键词跨层技术发展时间图"><g v-for="lane in layout.lanes" :key="lane.id"><rect x="0" :y="lane.y-30" :width="width" :height="lane.height" :fill="lane.tone" opacity=".04"/><rect x="0" :y="lane.y-30" width="5" :height="lane.height" :fill="lane.tone"/><text x="16" :y="lane.y+2" :fill="lane.tone" font-size="16" font-weight="700">{{lane.label.slice(0,9)}}</text><text v-if="lane.label.length>9" x="16" :y="lane.y+27" :fill="lane.tone" font-size="16" font-weight="700">{{lane.label.slice(9)}}</text><line x1="0" :x2="width" :y1="lane.y-30+lane.height" :y2="lane.y-30+lane.height" stroke="#e6e3e8"/></g><line v-for="(year,i) in years" :key="year" :x1="220+i*148" :x2="220+i*148" y1="20" :y2="layout.height-40" stroke="#dddfe6" stroke-dasharray="3 5"/><g class="chronology-edges"><path v-for="e in edges" :key="e.id" :d="path(e)" fill="none" :stroke="e.from.tone" :stroke-width="active&&(neighbors.has(e.source)&&neighbors.has(e.target))?2.8:1.4" :opacity="active ? ((e.source===active.id||e.target===active.id) ? .8 : .05) : .3" :stroke-dasharray="e.kind==='shared_work'?'3 4':null"><title>{{e.label}}</title></path></g><g v-for="p in layout.points" :key="p.id" class="chronology-node" :class="{selected:active?.id===p.id}" :opacity="active&&!neighbors.has(p.id)?.75:1" tabindex="0" role="button" :aria-label="`${p.year} · ${p.topic_label} · ${p.label}`" @click="select(p)" @keydown.enter="select(p)" @mouseenter="focus=p.id" @mouseleave="focus=''" @focus="focus=p.id" @blur="focus=''"><rect :x="p.x-63" :y="p.y-19" width="139" height="39" rx="7" fill="white" :stroke="p.tone" :stroke-width="active?.id===p.id?2:1"/><rect :x="p.x-63" :y="p.y-19" width="139" height="39" rx="7" :fill="p.tone" opacity=".09"/><circle :cx="p.x-53" :cy="p.y" r="3.5" :fill="p.tone"/><text :x="p.x-44" :y="p.y-2" font-size="12.4" font-weight="650" fill="#344155">{{short(p.topic_label)}}</text><text :x="p.x-44" :y="p.y+12" font-size="10.5" :fill="p.tone">{{p.year}} · {{short(p.label,72)}}</text><title>{{p.topic_label}} · {{p.year}}\n{{p.title}}</title></g></svg></div></div><div class="chronology-caption"><template v-if="active"><b>{{active.year}} · {{active.topic_label}}</b><span>{{active.title}}</span><a :href="safeUrl(active.url)" target="_blank" rel="noopener">成果原文 ↗</a></template><template v-else><span>横向看时间，纵向看技术层；选择节点查看代表成果与相邻联系。</span><small>实线：方法联系　虚线：同一成果</small></template></div></div></template>
